"""Bilingual executive studies and accordion-preserving portfolio integration."""
from pathlib import Path
import json,shutil,html
from bs4 import BeautifulSoup
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];PORT=ROOT.parent/'portifolio-sellerscope-publish';REPO='https://github.com/lucasmenghi/flightscope'
def main():
    m=json.loads((ROOT/'reports/metrics.json').read_text());d=json.loads((ROOT/'reports/data_manifest.json').read_text());f=json.loads((ROOT/'reports/frozen_config.json').read_text());n=m['selected'];b=m['logistic_baseline'];scenarios=json.loads((ROOT/'reports/capacity_scenarios.json').read_text())
    Image.open(ROOT/'assets/executive-cover.png').convert('RGB').save(ROOT/'assets/flightscope-cover.webp',quality=90,method=6)
    css=(ROOT/'assets/study.css').read_text(encoding='utf-8')+'\n:root{--ink:#1e2d43;--teal:#315780;} .hero a,.hero .eyebrow{color:#315780;} .hero{background:#f5f7fa;} .stats{grid-template-columns:repeat(4,minmax(0,1fr));} @media(max-width:760px){.stats{grid-template-columns:repeat(2,minmax(0,1fr));}}\n'
    source_rows=sum(x['source_rows'] for x in d['sources']);ci=m['ap_delta_day_bootstrap95'];delta=n['average_precision']-b['average_precision']
    for pt in [True,False]:
        filename='flightscope.html' if pt else 'flightscope-en.html';other='flightscope-en.html' if pt else 'flightscope.html';listing='projetos.html' if pt else 'projects.html'
        title='Antecipar risco, priorizar atenção' if pt else 'Anticipate risk, prioritize attention'
        intro='Classificação do risco de atraso na partida com registros oficiais de companhias aéreas. Um case de planejamento operacional com comparação de modelos, calibração e teste temporal.' if pt else 'Departure-delay risk classification using official airline records. An operational planning case with model comparisons, calibration and temporal testing.'
        problem='Uma equipe com capacidade limitada precisa priorizar voos para acompanhamento e comunicação. O alvo é partida com atraso ≥15 minutos (DepDel15 do BTS), não atraso na chegada. O modelo reconhece associações no histórico; não demonstra que alertar um voo reduz seu atraso.' if pt else 'A capacity-limited team needs to prioritize flights for monitoring and communication. The target is departure delay ≥15 minutes (BTS DepDel15), not arrival delay. The model recognizes historical associations; it does not establish that flagging a flight reduces its delay.'
        data=f'BTS Reporting Carrier On-Time Performance: 12 arquivos mensais de 2025, {source_rows:,} registros na fonte. Amostra de 15.000 voos por mês, total de 180.000, selecionada pelas menores chaves SHA256 sem consultar o alvo. Voos domésticos reportados, operados e com partida observada; cancelamentos excluídos e desvios mantidos quando há rótulo de partida.' if pt else f'BTS Reporting Carrier On-Time Performance: 12 monthly files from 2025, {source_rows:,} source records. Sample of 15,000 flights per month, 180,000 total, selected by lowest SHA256 keys without consulting the target. Reported domestic operated flights with observed departures; cancellations excluded, diversions retained when departure labels exist.'
        inputs='Entradas: companhia, aeroportos de origem/destino, horário programado, mês, dia da semana, distância e duração programada. Horário e mês têm representação cíclica. Horários reais, causas de atraso, taxiamento e status de cancelamento ficam fora das features. Os arquivos são retrospectivos: os horários programados não foram auditados como snapshots conhecidos no instante da previsão.' if pt else 'Inputs: carrier, origin/destination airports, scheduled time, month, weekday, distance and scheduled duration. Time and month use cyclic representations. Actual times, delay causes, taxiing and cancellation status are excluded from features. Files are retrospective: schedule fields were not audited as snapshots known at prediction time.'
        method=f'Quatro candidatos: duas regressões logísticas e dois LightGBM. Duas janelas expansivas: jan–abr → mai–jun e jan–jun → jul–ago. Seleção por average precision média: {f["selected"]}. Refit em jan–ago (120.000 voos); calibração em setembro (15.000); limiar no percentil 80 de outubro (15.000). Teste final somente em novembro–dezembro (30.000), após congelamento.' if pt else f'Four candidates: two logistic regressions and two LightGBM models. Two expanding windows: Jan–Apr → May–Jun and Jan–Jun → Jul–Aug. Mean average-precision selection: {f["selected"]}. Refit on Jan–Aug (120,000 flights); September calibration (15,000); threshold at October 80th percentile (15,000). Final test only on November–December (30,000), after freezing.'
        comparison=('O selecionado superou a regressão logística em AP no teste.' if delta>0 else 'A regressão logística teve AP igual ou maior no teste. O case preserva esse resultado, sem retreinar a partir do teste.') if pt else ('The selected model outperformed logistic regression in final-test AP.' if delta>0 else 'Logistic regression had equal or higher final-test AP. This result is retained, without test-driven retraining.')
        limits='Uma semente, um ano e voos domésticos dos EUA. Meses têm o mesmo tamanho amostral, diferente da distribuição real de tráfego nacional. Sem previsão meteorológica, condições em tempo real ou histórico da rotação da aeronave. Não cobre cancelamentos, não estabelece eficácia em outro ano e não mede economia ou ROI. Calibração e tamanho da fila podem variar no tempo.' if pt else 'One seed, one year and US domestic flights. Months have equal sample sizes, unlike actual national traffic weights. No weather forecasts, real-time conditions or aircraft rotation history. Does not cover cancellations, establish performance in another year or measure savings/ROI. Calibration and queue size may drift over time.'
        action='Próximo passo: reavaliar em outro ano e estação, validar a disponibilidade dos campos no momento da previsão e testar um piloto com humanos. Medir precisão dos alertas, atrasos não sinalizados, carga de trabalho e efeito das intervenções. O aplicativo local permite inferência; esta página é um diagnóstico histórico.' if pt else 'Next step: evaluate another year/season, validate feature availability at prediction time and pilot with humans. Measure alert precision, missed delays, workload and intervention effects. The local app supports inference; this page is a historical diagnostic.'
        comparison+=(f' O ganho de ranking é modesto e o limiar de outubro perdeu cobertura: sinalizou {n["recall"]:.1%} dos atrasos no teste. Revalidar antes de uso operacional.' if pt else f' Ranking improvement is modest and the October threshold lost coverage: it flagged {n["recall"]:.1%} of final-test delays. Revalidate before operational use.')
        headings=['Problema e decisão','Dados e momento da previsão','Modelos e congelamento','Resultado no período futuro','Capacidade de acompanhamento','Limites e piloto'] if pt else ['Problem and decision','Data and prediction time','Models and freezing','Results on a later period','Monitoring capacity','Limits and pilot']
        rows=''.join(f'<tr><td>{name}</td><td>{x["average_precision"]:.3f}</td><td>{x["roc_auc"]:.3f}</td><td>{x["brier"]:.3f}</td><td>{x["precision_at20"]:.1%}</td><td>{x["recall_at20"]:.1%}</td><td>{x["lift_at20"]:.2f}×</td></tr>' for name,x in [(f['selected'],n),('Logistic baseline',b)])
        body=f'''<header class="hero"><div class="wrap"><nav><a href="LISTING">← {'Portfólio' if pt else 'Portfolio'}</a><div><a href="{other}">{'English' if pt else 'Português'}</a><a href="{REPO}" target="_blank" rel="noopener">GitHub ↗</a></div></nav><img class="hero-art" src="COVER" width="1672" height="941" alt="FlightScope — {'capa editorial de previsão de atrasos aéreos' if pt else 'editorial flight-delay forecasting cover'}"><p class="eyebrow">FLIGHTSCOPE / AIRLINE OPERATIONS / CLASSIFICATION</p><h1>{title}</h1><p class="lead">{intro}</p><a class="button" href="#results">{'Explorar resultados' if pt else 'Explore results'}</a><a class="button" href="{REPO}" target="_blank" rel="noopener">{'Ver projeto' if pt else 'View project'}</a></div></header><main class="wrap" id="main"><section><p class="eyebrow">01 / BUSINESS UNDERSTANDING</p><h2>{headings[0]}</h2><p>{problem}</p></section><section><p class="eyebrow">02 / DATA UNDERSTANDING &amp; PREPARATION</p><h2>{headings[1]}</h2><p>{data}</p><p>{inputs}</p></section><section><p class="eyebrow">03 / MODELING</p><h2>{headings[2]}</h2><p>{method}</p><figure><img class="plot" src="FIGURESdevelopment.png" loading="lazy" alt="Four candidate models in two temporal validation windows"></figure></section><section id="results"><p class="eyebrow">04 / EVALUATION</p><h2>{headings[3]}</h2><p class="lead">{comparison}</p><div class="table-wrap"><table><thead><tr><th>{'Modelo' if pt else 'Model'}</th><th>AP</th><th>ROC AUC</th><th>Brier ↓</th><th>Precision@20%</th><th>Recall@20%</th><th>Lift@20%</th></tr></thead><tbody>{rows}</tbody></table></div><p class="note">AP = average precision. {'Prevalência de atraso no teste' if pt else 'Final-test delay prevalence'}: {m['test_delay_rate']:.1%}. {'Diferença de AP selecionado − referência' if pt else 'AP difference selected − baseline'}: {delta:+.3f}; bootstrap 95%: [{ci[0]:+.3f}, {ci[1]:+.3f}]. {'300 reamostragens pareadas por dia; dependência entre dias não modelada.' if pt else '300 paired day-block resamples; dependence between days not modeled.'}</p><figure><img class="plot" src="FIGURESprecision_recall.png" loading="lazy" alt="Final-test precision recall comparison"></figure><figure><img class="plot" src="FIGUREScalibration.png" loading="lazy" alt="Final-test probability reliability"></figure><p>{'Limiar congelado' if pt else 'Frozen threshold'}: {n['threshold']:.3f}; {'fila no teste' if pt else 'final-test queue'}: {n['queue_rate']:.1%}; precision: {n['precision']:.1%}; recall: {n['recall']:.1%}. {'Esse limiar não garante fila de 20% no futuro.' if pt else 'This threshold does not guarantee a 20% future queue.'}</p><figure><img class="plot" src="FIGURESmonthly_stability.png" loading="lazy" alt="November and December AP and queue stability"></figure></section><section><p class="eyebrow">05 / HISTORICAL CAPACITY SCENARIO</p><h2>{headings[4]}</h2><p>{'Selecione a fração dos 30.000 voos de teste a acompanhar pelo ranking do modelo. Este cenário usa desfechos históricos e é separado do limiar congelado. Não é nova otimização nem garantia para uma operação real.' if pt else 'Choose the share of 30,000 final-test flights to monitor using model ranking. This scenario uses historical outcomes and is separate from the frozen threshold. It is not new optimization or a real-operation guarantee.'}</p><label for="capacity">{'Capacidade de acompanhamento' if pt else 'Monitoring capacity'}</label><select id="capacity">{''.join(f'<option value="{x["capacity"]}" '+('selected' if x['capacity']==20 else '')+f'>{x["capacity"]}%</option>' for x in scenarios)}</select><div class="stats">{''.join(f'<article class="stat"><output class="number" id="{key}"></output><small>{label}</small></article>' for key,label in [('queue','Voos selecionados' if pt else 'Selected flights'),('identified','Atrasos identificados' if pt else 'Delays identified'),('precision','Precisão da fila' if pt else 'Queue precision'),('lift','Lift vs. seleção aleatória' if pt else 'Lift vs. random selection')])}</div></section><section><p class="eyebrow">06 / LIMITATIONS &amp; DEPLOYMENT</p><h2>{headings[5]}</h2><p>{limits}</p><p>{action}</p><a class="button" href="{REPO}/blob/main/notebooks/01_flight_delay_case.ipynb" target="_blank" rel="noopener">Notebook ↗</a><a class="button" href="{REPO}/blob/main/docs/model_card.md" target="_blank" rel="noopener">Model card ↗</a></section></main><footer class="wrap"><p class="note">Lucas Menghi • {'Case independente, sem vínculo ou endosso do BTS ou de companhias aéreas. Capa conceitual gerada com IA; gráficos calculados com dados reais.' if pt else 'Independent case, no BTS or airline affiliation/endorsement. AI-generated conceptual cover; charts computed from real data.'} <a href="https://www.transtats.bts.gov/tables.asp?qo_vq=EFD">BTS / TranStats</a> · <a href="https://www.transtats.bts.gov/Fields.asp?gnoyr_VQ=FGJ">{'Dicionário de dados' if pt else 'Data dictionary'}</a></p></footer><script>const scenarios={json.dumps(scenarios)};function update(){{const value=Number(document.getElementById('capacity').value);const row=scenarios.find(x=>x.capacity===value).selected;for(const key of ['queue','identified'])document.getElementById(key).textContent=row[key].toLocaleString('{('pt-BR' if pt else 'en-US')}');document.getElementById('precision').textContent=(100*row.precision).toFixed(1)+'%';document.getElementById('lift').textContent=row.lift.toFixed(2)+'×';}}document.getElementById('capacity').addEventListener('change',update);update();</script>'''
        for repo in [True,False]:
            cover='../assets/flightscope-cover.webp' if repo else '../images/thumbs/flightscope-cover.webp';figures='../reports/figures/' if repo else '../images/flightscope/';portfolio='https://lucasmenghi.github.io/portifolio/projects/'+listing if repo else listing
            content=f'<!DOCTYPE html><html lang="{("pt-BR" if pt else "en")}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FlightScope | Lucas Menghi</title><meta name="description" content="{html.escape(intro)}"><meta property="og:image" content="https://lucasmenghi.github.io/portifolio/images/thumbs/flightscope-cover.webp"><style>{css}</style></head><body>'+body.replace('COVER',cover).replace('FIGURES',figures).replace('LISTING',portfolio)+'</body></html>'
            dest=ROOT/'docs'/filename if repo else PORT/'projects'/filename;dest.write_text(content,encoding='utf-8')
        card=f'''<article class="col-6 work-item project-card"><h4 class="project-title">FlightScope — Airline Delay Intelligence</h4><a class="image fit thumb" href="{filename}"><img src="../images/thumbs/flightscope-cover.webp" alt="FlightScope — {'previsão de atrasos aéreos' if pt else 'airline departure delay prediction'}" loading="lazy"/></a><div class="project-content"><h5>{'Contexto' if pt else 'Context'}:</h5><p>{'Classificação de risco de atraso na partida (≥15 min) para apoiar a priorização de acompanhamento operacional.' if pt else 'Departure-delay risk classification (≥15 min) to support prioritization of operational monitoring.'}</p><h5>{'Abordagem' if pt else 'Approach'}:</h5><p>{'180 mil voos reais do BTS em 2025; quatro candidatos; janelas temporais; calibração e limiar definidos antes do teste final.' if pt else '180,000 real BTS flights from 2025; four candidates; temporal windows; calibration and threshold fixed before final testing.'}</p><h5>{'Resultado' if pt else 'Result'}:</h5><p>AP: {n['average_precision']:.3f}; ROC AUC: {n['roc_auc']:.3f}. {'Ao priorizar 20% dos voos' if pt else 'Prioritizing 20% of flights'}: lift {n['lift_at20']:.2f}×; recall {n['recall_at20']:.1%}. {'Teste histórico, sem eficácia operacional comprovada.' if pt else 'Historical test, no demonstrated operational efficacy.'}</p><p class="project-tags">Python · Scikit-learn · LightGBM · Classification · CRISP-DM · Calibration · Streamlit</p></div><a class="button project-button" href="{filename}">{'Ver estudo' if pt else 'Read case study'} →</a><a class="button project-button" href="{REPO}" target="_blank" rel="noopener">{'Ver projeto' if pt else 'View project'} →</a></article>'''
        for port in [PORT,ROOT.parent/'portifolio']:
            path=port/'projects'/listing;soup=BeautifulSoup(path.read_text(encoding='utf-8'),'html.parser');section=soup.find(id='classificacao' if pt else 'classification')
            if section is None:raise ValueError('Classification section missing')
            for existing in section.select('article.project-card'):
                if 'FlightScope' in existing.get_text():existing.decompose()
            section.select_one('.project-grid').append(BeautifulSoup(card,'html.parser').article)
            count=len(section.select('article.project-card'));section.select_one('.subarea-count').string=f'{count} '+('projetos publicados' if pt else 'published projects')
            category=section.find_parent(class_='project-category');category.select_one('.category-count').string=f'{len(category.select("article.project-card"))} '+('projetos' if pt else 'projects')
            path.write_text(str(soup),encoding='utf-8')
    dest=PORT/'images/flightscope';dest.mkdir(exist_ok=True)
    for file in (ROOT/'reports/figures').glob('*.png'):shutil.copy2(file,dest/file.name)
    shutil.copy2(ROOT/'assets/flightscope-cover.webp',PORT/'images/thumbs/flightscope-cover.webp')
    primary=ROOT.parent/'portifolio'
    for name in ['flightscope.html','flightscope-en.html']:shutil.copy2(PORT/'projects'/name,primary/'projects'/name)
    shutil.copytree(dest,primary/'images/flightscope',dirs_exist_ok=True);shutil.copy2(ROOT/'assets/flightscope-cover.webp',primary/'images/thumbs/flightscope-cover.webp')
    print('Bilingual studies and classification cards built; accordion hierarchy preserved.')
if __name__=='__main__':main()
